// Marketing frequency cap: at most MAX_PER_DAY marketing messages per customer
// per local calendar day (midnight to midnight in the customer's time zone),
// across all channels and all worker processes.
//
// State: one file per reserved message in STATE_DIR. A slot file is created with
// the exclusive flag ("wx"), which the filesystem makes atomic across processes.
// No lock files exist, so a crashed or restarted worker cannot leave a stale lock.
// A slot that exists counts as sent, even if the worker died right after creating it.
import { open, mkdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import path from 'node:path';

const MAX_PER_DAY = 2;
const CHANNELS = new Set(['sms', 'email', 'push']);

const deny = (rule) => ({ allowed: false, rule });

function localDay(now, timeZone) {
  // Throws RangeError for an unknown time zone.
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now);
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

async function fsyncDir(dir) {
  try {
    const fd = await open(dir, 'r');
    try {
      await fd.sync();
    } finally {
      await fd.close();
    }
  } catch {
    // Directory fsync is not supported on every platform; the slot file is still created.
  }
}

export async function reserve({ userId, timeZone, channel, now }) {
  if (typeof userId !== 'string' || userId === '') return deny('invalid-user');
  if (!CHANNELS.has(channel)) return deny('invalid-channel');
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return deny('invalid-time');
  const stateDir = process.env.STATE_DIR;
  if (!stateDir) return deny('no-state-dir');

  let day;
  try {
    day = localDay(now, timeZone);
  } catch {
    return deny('invalid-time-zone');
  }

  // Fail closed on any input or storage problem: a held message is cheaper than a fourth one.
  const dir = path.resolve(stateDir);
  await mkdir(dir, { recursive: true });
  const userKey = createHash('sha256').update(userId).digest('hex');

  for (let slot = 1; slot <= MAX_PER_DAY; slot++) {
    const file = path.join(dir, `mkt-${userKey}-${day}-${slot}.json`);
    let fh;
    try {
      fh = await open(file, 'wx');
    } catch (err) {
      if (err.code === 'EEXIST') continue; // slot taken by another call or process
      throw err;
    }
    try {
      await fh.writeFile(
        JSON.stringify({ userId, timeZone, channel, day, slot, at: now.toISOString() }),
      );
      await fh.sync();
    } finally {
      await fh.close();
    }
    await fsyncDir(dir);
    return { allowed: true, rule: '' };
  }
  return deny('daily-cap');
}

import { spawn } from 'node:child_process';
import { mkdtempSync, readdirSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert';

const bot = process.argv[2];
const dir = path.join(mkdtempSync(path.join(os.tmpdir(), 'st-')), 'nested');
process.env.STATE_DIR = dir;
const { reserve } = await import(bot);

// Worker mode: run N concurrent calls and print allowed count.
if (process.argv[3] === 'worker') {
  const rs = await Promise.all(Array.from({ length: 10 }, (_, i) =>
    reserve({ userId: 'u1', timeZone: 'Asia/Tokyo', channel: ['sms', 'email', 'push'][i % 3], now: new Date('2026-10-23T05:00:00Z') })));
  console.log(rs.filter((r) => r.allowed).length);
  process.exit(0);
}

const t = (iso, tz = 'Asia/Tokyo', userId = 'a') => reserve({ userId, timeZone: tz, channel: 'sms', now: new Date(iso) });
// Tokyo: 2026-10-23T14:59Z = 23:59 local; 15:00Z = 00:00 next day.
assert.deepEqual(await t('2026-10-23T14:00:00Z'), { allowed: true, rule: '' });
assert.deepEqual(await t('2026-10-23T14:30:00Z'), { allowed: true, rule: '' });
assert.deepEqual(await t('2026-10-23T14:59:59Z'), { allowed: false, rule: 'daily-cap' });
assert.equal((await t('2026-10-23T15:00:00Z')).allowed, true, 'new local day');
// New York same instants: still 10-23 local, separate counter by tz-day key for the same user.
assert.equal((await t('2026-10-23T04:00:00Z', 'America/New_York', 'b')).allowed, true); // 10-23 00:00 EDT
assert.equal((await t('2026-10-23T03:59:00Z', 'America/New_York', 'b')).allowed, true); // 10-22 23:59 EDT
assert.equal((await t('2026-10-23T03:58:00Z', 'America/New_York', 'b')).allowed, true); // 10-22 second
assert.equal((await t('2026-10-23T03:57:00Z', 'America/New_York', 'b')).allowed, false); // 10-22 third
assert.equal((await t('x', 'Asia/Tokyo', 'c')).allowed, false);
assert.equal((await t('2026-10-23T00:00:00Z', 'Nope/Zone', 'c')).rule, 'invalid-time-zone');

// 8 processes x 10 concurrent calls for one user: exactly 2 allowed total.
const outs = await Promise.all(Array.from({ length: 8 }, () => new Promise((res) => {
  const p = spawn(process.execPath, [process.argv[1], bot, 'worker'], { env: { ...process.env, STATE_DIR: dir + '2' } });
  let o = ''; p.stdout.on('data', (d) => (o += d)); p.on('close', () => res(Number(o)));
})));
const total = outs.reduce((a, b) => a + b, 0);
console.log('per-process allowed', outs, 'total', total);
assert.equal(total, 2);
// Restart: a fresh process sees the state.
const again = await new Promise((res) => {
  const p = spawn(process.execPath, [process.argv[1], bot, 'worker'], { env: { ...process.env, STATE_DIR: dir + '2' } });
  let o = ''; p.stdout.on('data', (d) => (o += d)); p.on('close', () => res(Number(o)));
});
assert.equal(again, 0);
console.log('ALL OK', readdirSync(dir + '2').length, 'files');
